        if p is None:
            return None
        x, y = p
        if valid_num(x) and valid_num(y):
            return (x, y)
        return None

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def move_toward(src, dst):
        return [clamp_step(dst[0] - src[0]), clamp_step(dst[1] - src[1])]

    def move_away(src, dst):
        return [clamp_step(src[0] - dst[0]), clamp_step(src[1] - dst[1])]

    def iter_points(obj):
        if obj is None:
            return
        if isinstance(obj, dict):
            p = to_point(obj)
            if p is not None:
